import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {number[]} position - [x, y, z]
 * @property {number[]} rotation - [x, y, z] in radians
 * @property {number[]} scale - [x, y, z]
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {any} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {Object.<string, Function>} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates a textured plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const {
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {},
    cinematicPrimitives = [],
    textContent = null,
  } = config;

  const { imageUrl } = assets;

  // Load texture (synchronous via cached loader)
  const tex = ctx.textureLoader(imageUrl);

  // Atlas region defines a 512×320 source rect → aspect 1.6
  const aspect = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // Node‑based basic material displaying the texture
  const material = new MeshBasicNodeMaterial({ map: tex });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // Apply any cinematic primitives specified in the config
  for (const primitive of cinematicPrimitives) {
    const fn = ctx.primitives[primitive.name];
    if (typeof fn === 'function') {
      fn(mesh, primitive.params);
    }
  }

  // Event handler container (empty for this node)
  mesh.userData.handlers = {};

  // Store timelines (none for this node but kept for consistency)
  const timelines = [];

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Do not dispose tex here: it is managed by the texture loader cache.
    timelines.forEach((tl) => tl.kill && tl.kill());
    timelines.length = 0;
  };

  return mesh;
}
